    document.getElementById('home-evidence-gates').innerHTML=[['Stated test contracts',7],['Specified mathematical models',7],['Finite checks in declared scopes',7],['Native-Python numerical parity',7],['Independent replication & robustness',0],['Measured scale-up',0],['Generalized application',0]].map(([label,n])=>`<div class="home-gate-row"><span>${label}</span><span class="home-gate-bar"><i style="width:${100*n/7}%"></i></span><strong>${n}/7</strong></div>`).join('');
