    function demo(step){const s={...E.initial('welcome-demo'),global:step>=1,refined:step>=2,permission:false},r=E.evaluate(s);document.getElementById('home-demo-count').textContent=r.coverage+' / 2';document.getElementById('home-demo-map').innerHTML=`<div class="home-demo-pair ${step<2?'home-merged':''}">${[0,1].map(x=>`<div class="home-demo-case"><span>Case 0${x}</span><strong>${r.point[x]===null?'?':r.point[x]===0?'Safe':'Harmful'}</strong><small>Point judgment</small></div>`).join('')}</div><div class="home-demo-receiver">${step<2?'One receiving class · unresolved':'Two receiving classes · safe / harmful'}</div>`;document.getElementById('home-demo-explanation').textContent=['Neither repair can yet reach a justified receiving answer.','The rule now warrants opposite point judgments. The receiving view still merges the cases.','Both changes work together: two distinct warranted receiving judgments, with evidence unchanged.'][step];for(const b of front.querySelectorAll('[data-home-demo]'))b.setAttribute('aria-pressed',String(Number(b.dataset.homeDemo)===step));}
    document.getElementById('home-mersia-definition').addEventListener('click',()=>G.show('mersia'));
    document.getElementById('home-progress-definition').addEventListener('click',()=>G.show('evidencecoverage'));
    document.getElementById('home-run-sequence').addEventListener('click',()=>{const status=document.getElementById('home-sequence-result');try{const rows=lab.runSequence(STAGES.map(s=>s.id));status.textContent=rows.every(r=>r.passed)?'All seven scoped fixtures passed. Each stage reports its own bounded result below.':'The sequence stopped at a failed stage.';let details=document.getElementById('home-sequence-details');if(!details){details=document.createElement('details');details.id='home-sequence-details';status.after(details);}details.replaceChildren();const summary=document.createElement('summary');summary.textContent='Inspect the seven result envelopes';details.appendChild(summary);const list=document.createElement('ol');for(const r of rows){const li=document.createElement('li');li.textContent=r.summary;list.appendChild(li);}details.appendChild(list);}catch(e){status.textContent='Sequence could not run: '+e.message;}});
    demo(0);G.annotate(front);
